const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});
let c = 0;

rl.on('line', (d) => {
  const [n, m] = d.split(' ').map(Number);

  if (m === 0 || m === 1) {
    console.log(1);
  }
  else if (n === m) {
    console.log(0);
  }
  else if (n / 2 > m) {
    console.log(m);
  }
  else {
    console.log(n - m);
  }

  c++;
});
